import itertools
for a in [59,60]:
 vals=list(range(a,a+12))
 print('start',a)
 for diag in itertools.combinations(vals,2):
  if sum(diag)==12*a-584:
   rem=[v for v in vals if v not in diag]
   rows=[]
   for sub in itertools.combinations(rem,5):
    if sum(sub)==325:
     rows.append(sub)
   print(' diag',diag,'row subsets',len(rows),rows)
